document.addEventListener('change',async e=>{if(e.target.id==='importFile'){const file=e.target.files?.[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(!['products','spools','prints','sales'].every(k=>Array.isArray(incoming[k])))throw Error('Invalid backup');if(!confirm('This will replace all existing local records. Continue?'))return;data={...blank(),...incoming};modal=null;save()}catch(err){alert('Cannot import backup: '+err.message)}}if(e.target.id==='f_productId'){const p=product(e.target.value);if(p&&modal==='sale'){$('#f_price').value=p.price;const area=$('#saleFilamentArea');if(area)area.innerHTML=isMulti(p)?multiEditor(defaultMulti(p).length?defaultMulti(p):starterMulti()):select('spoolId','Printed colour',data.spools.map(s=>[s.id,s.colorName+' · '+s.brand+' '+s.material]),p.filamentId||data.spools[0]?.id);if($('#f_grams'))$('#f_grams').value=p.grams;if($('#f_hours'))$('#f_hours').value=p.hours;updateSalePreview()}if(p&&modal==='print'){$('#f_grams').value=p.grams;$('#f_hours').value=p.hours;updateFilamentEstimate()}}});

