document.addEventListener('click',e=>{if(modal==='quote'&&e.target.closest('[data-act="add-multi"],[data-act="remove-multi"]'))updateQuotePreview()});
document.addEventListener('click',e=>{const act=e.target.closest('[data-act]')?.dataset.act;if(!act)return;const match=/^(quote-decline|quote-reopen|quote-delete):(.+)$/.exec(act);if(match){e.preventDefault();e.stopImmediatePropagation();changeQuoteStatus(match[1],match[2])}},true);
document.addEventListener('click',e=>{
const act=e.target.closest('[data-act]')?.dataset.act;
if(!act||!/^queue-(new|custom|product|edit:|status:|move:|delete:)/.test(act))return;
e.preventDefault();e.stopImmediatePropagation();
if(act==='queue-new'){modal='queue-pick';editId=null}
else if(act==='queue-custom'||act==='queue-product'){queueMode=act==='queue-product'?'product':'custom';editId=null;modal='queue-editor'}
else if(act.startsWith('queue-edit:')){editId=act.slice(11);modal='queue-editor'}
else if(act.startsWith('queue-status:')){const [,qid,status]=act.split(':'),q=data.queue.find(x=>x.id===qid);if(q&&['todo','printing','done'].includes(status)){q.status=status;save();return}}
else if(act.startsWith('queue-delete:')){const qid=act.slice(13);if(!confirm('Remove this print from the queue?'))return;data.queue=data.queue.filter(x=>x.id!==qid);save();return}
else if(act.startsWith('queue-move:')){const [,qid,direction]=act.split(':'),q=data.queue.find(x=>x.id===qid);if(q){const same=data.queue.filter(x=>x.status===q.status),i=same.indexOf(q),other=same[i+(direction==='up'?-1:1)];if(other){const a=data.queue.indexOf(q),b=data.queue.indexOf(other);[data.queue[a],data.queue[b]]=[data.queue[b],data.queue[a]];save()}return}}
render();
},true);
document.addEventListener('submit',e=>{
if(e.target.id!=='queueForm')return;
e.preventDefault();e.stopImmediatePropagation();
const f=Object.fromEntries(new FormData(e.target)),quantity=Number(f.quantity),old=data.queue.find(x=>x.id===editId),mode=old?.mode||queueMode;
if(!Number.isInteger(quantity)||quantity<1||quantity>9999)return alert('Enter a quantity between 1 and 9999.');
const p=mode==='product'?product(f.productId):null,name=p?.name||String(f.name||'').trim();if(!name)return alert('Give this print a name.');
const s=spool(f.spoolId),item={id:old?.id||id(),mode,productId:p?.id||null,name,quantity,spoolId:s?.id||'',colorName:s?.colorName||'',customer:String(f.customer||'').trim(),notes:String(f.notes||'').trim(),status:old?.status||'todo',created:old?.created||today()};
if(old)data.queue=data.queue.map(x=>x.id===old.id?item:x);else data.queue.push(item);
modal=null;editId=null;save();
},true);
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-act^="chart-days:"]');
 if(!button)return;
 const days=Number(button.dataset.act.split(':')[1]);
 if(days!==7&&days!==30)return;
 e.preventDefault();e.stopImmediatePropagation();salesChartDays=days;render();
},true);
render();
